styles.css:
.tp-root {
  height: 100%;
  display: flex;
  flex-direction: column;
  background: rgb(var(--c-bg-base));
  color: rgb(var(--c-text-primary));
  font-size: 13px;
}
.tp-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px;
  border-bottom: 1px solid rgb(var(--c-border) / 0.1);
}
.tp-title { display: flex; align-items: center; gap: 8px; font-weight: 500; }
.tp-dir { display: flex; gap: 6px; padding: 8px 16px; }
.tp-dir-btn {
  padding: 4px 12px;
  border-radius: 9999px;
  border: 1px solid rgb(var(--c-border) / 0.15);
  font-size: 12px;
  color: rgb(var(--c-text-secondary));
  background: transparent;
  cursor: pointer;
}
.tp-dir-btn:hover { background: rgb(var(--c-bg-hover)); }
.tp-dir-on {
  border-color: rgb(var(--c-primary));
  color: rgb(var(--c-primary));
  background: rgb(var(--c-primary) / 0.1);
}
.tp-body { flex: 1; display: flex; flex-direction: column; gap: 8px; padding: 0 16px 16px; overflow: hidden; }
.tp-area {
  flex: 1;
  min-height: 72px;
  padding: 10px;
  border-radius: 8px;
  border: 1px solid rgb(var(--c-border) / 0.15);
  background: rgb(var(--c-bg-surface));
  color: rgb(var(--c-text-primary));
  font-size: 13px;
  resize: none;
  outline: none;
}
.tp-area:focus { border-color: rgb(var(--c-primary)); }
.tp-out {
  flex: 1;
  min-height: 72px;
  padding: 10px;
  border-radius: 8px;
  border: 1px solid rgb(var(--c-border) / 0.15);
  background: rgb(var(--c-bg-elevated));
  overflow: auto;
  white-space: pre-wrap;
}
.tp-actions { display: flex; gap: 8px; }
.tp-btn {
  flex: 1;
  padding: 6px 0;
  border-radius: 8px;
  border: 1px solid rgb(var(--c-border) / 0.15);
  background: transparent;
  color: rgb(var(--c-text-secondary));
  font-size: 12px;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
}
.tp-btn:hover:not(:disabled) { background: rgb(var(--c-bg-hover)); color: rgb(var(--c-text-primary)); }
.tp-btn:disabled { opacity: 0.4; cursor: default; }
.tp-primary {
  background: rgb(var(--c-primary));
  border-color: rgb(var(--c-primary));
  color: #fff;
}
.tp-error {
  padding: 8px 12px;
  font-size: 12px;
  border-radius: 6px;
  border: 1px solid rgb(var(--c-status-danger) / 0.35);
  color: rgb(var(--c-status-danger));
  background: rgb(var(--c-status-danger) / 0.06);
}
.tp-hist {
  max-height: 160px;
  overflow: auto;
  border: 1px solid rgb(var(--c-border) / 0.12);
  border-radius: 8px;
}
.tp-hist-item {
  width: 100%;
  text-align: left;
  padding: 8px 12px;
  background: transparent;
  border: 0;
  border-bottom: 1px solid rgb(var(--c-border) / 0.08);
  cursor: pointer;
}
.tp-hist-item:hover { background: rgb(var(--c-bg-hover)); }
